import XCTest

class BlueskyUITest: XCTestCase {
    override func setUp() {
        super.setUp()
        continueAfterFailure = false
    }

    func testOpenProfileDialog() {
        let app = XCUIApplication()
        app.launch()

        // Wait for the dialog to appear
        sleep(1)

        // Find and tap the Open button
        let openButton = app.buttons.matching(NSPredicate(format: "label == 'Open'")).firstMatch
        if openButton.exists {
            openButton.tap()
        } else {
            // Try to find by other attributes
            let buttons = app.buttons.allElementsBoundByIndex
            for button in buttons {
                print("Button: \(button.label)")
                if button.label.contains("Open") {
                    button.tap()
                    break
                }
            }
        }

        // Wait for the profile to load
        sleep(2)
    }
}
EOF

